const managerAtLevel = `-- name: ManagerAtLevel :many
WITH RECURSIVE chain AS (
    SELECT e.id, e.manager_id, 0 AS lvl
    FROM employees e
    WHERE e.tenant_id = $1 AND e.id = $2
    UNION ALL
    SELECT m.id, m.manager_id, c.lvl + 1
    FROM chain c
    JOIN employees m ON m.id = c.manager_id AND m.status = 'ACTIVE'
    WHERE c.lvl < $3::int
)
SELECT id FROM chain WHERE lvl = $3::int
`

type ManagerAtLevelParams struct {
	TenantID int64
	ID       int64
	Levels   int32
}

// Walks the reporting line upwards: level 1 is the direct manager, level 2
// their manager, and so on. Returns at most one row, and none once the chain
// runs out - the person at the top reports to nobody, and a flow that climbs
// past them simply has no one left to ask.
func (q *Queries) ManagerAtLevel(ctx context.Context, arg ManagerAtLevelParams) ([]int64, error) {
	rows, err := q.db.Query(ctx, managerAtLevel, arg.TenantID, arg.ID, arg.Levels)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []int64
	for rows.Next() {
		var id int64
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const managerCycleExists = `-- name: ManagerCycleExists :one
WITH RECURSIVE chain AS (
  SELECT id, manager_id, ARRAY[id]::bigint[] AS visited
  FROM employees
  WHERE tenant_id = $2::bigint
    AND id = $3::bigint
  UNION ALL
  SELECT e.id, e.manager_id, c.visited || e.id
  FROM employees e
  JOIN chain c ON e.id = c.manager_id
  WHERE e.tenant_id = $2::bigint
    AND NOT e.id = ANY(c.visited)
)
SELECT EXISTS (
  SELECT 1 FROM chain WHERE id = $1::bigint
)
`

type ManagerCycleExistsParams struct {
	EmployeeID int64
	TenantID   int64
	ManagerID  int64
}

func (q *Queries) ManagerCycleExists(ctx context.Context, arg ManagerCycleExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, managerCycleExists, arg.EmployeeID, arg.TenantID, arg.ManagerID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

const recordLoginFailure = `-- name: RecordLoginFailure :one
UPDATE users
SET failed_count = failed_count + 1,
    locked_until = CASE
        WHEN failed_count + 1 >= 10 THEN greatest(locked_until, now() + interval '60 seconds')
        ELSE locked_until
    END,
    updated_at = now()
WHERE id = $1
RETURNING failed_count, locked_until
`

type RecordLoginFailureRow struct {
	FailedCount int32
	LockedUntil pgtype.Timestamptz
}

// Ten wrong passwords buy sixty seconds, and only ever pushed forward from
// now — the eleventh does not extend it to two minutes. Without the
// greatest(), somebody guessing keeps renewing the lock they put on another
// person, which is the punishment landing on the wrong side.
//
// The numbers are ERPNext's, and they are a pair rather than two choices. A
// short window is what makes this survivable when it is aimed at somebody on
// purpose: sixty seconds of being shut out, not a quarter of an hour. What
// pays for it is that ten guesses a minute is only harmless against a
// password worth having, which is why the strength policy landed in the same
// change and why neither may be relaxed without the other.
func (q *Queries) RecordLoginFailure(ctx context.Context, id int64) (RecordLoginFailureRow, error) {
	row := q.db.QueryRow(ctx, recordLoginFailure, id)
	var i RecordLoginFailureRow
	err := row.Scan(&i.FailedCount, &i.LockedUntil)
	return i, err
}

const recordLoginSuccess = `-- name: RecordLoginSuccess :exec
UPDATE users
SET failed_count = 0, locked_until = NULL, last_login_at = now(), updated_at = now()
WHERE id = $1
`

// Clears the deadline as well as the counter. Somebody who was locked at
// 09:00 and signs in at 09:20 has demonstrated the thing the lock was waiting
// to find out; leaving the timestamp behind would let a stale value refuse
// their next attempt.
func (q *Queries) RecordLoginSuccess(ctx context.Context, id int64) error {
	_, err := q.db.Exec(ctx, recordLoginSuccess, id)
	return err
}

